T_KERNEL_FUZZ.patch:
--- a/src/RimMandrake/WreckedMachines/Source/Kernel/RM_WreckedMachinesKernel.cs
+++ b/src/RimMandrake/WreckedMachines/Source/Kernel/RM_WreckedMachinesKernel.cs
@@ -89,7 +89,7 @@
             var want = new List<T>();
             AddAll(want, rowNamed, int.MaxValue);
             if (want.Count == 0 && rowCount > 0) AddAll(want, donor, rowCount);
-            AddAll(want, asLoaded, int.MaxValue);
+            if (asLoaded != null) foreach (T p in asLoaded) if (p != null && !donor.Contains(p) && !want.Contains(p)) want.Add(p);
             if (want.Count == 0) AddAll(want, donor, 1);
             return want;
         }

T_REPAIR_STATE_WALK.patch:
--- a/src/RimMandrake/WreckedMachines/Source/Kernel/RM_WreckedMachinesRepair.cs
+++ b/src/RimMandrake/WreckedMachines/Source/Kernel/RM_WreckedMachinesRepair.cs
@@ -142,7 +142,7 @@
             var back = new List<KeyValuePair<string, int>>();
             if (rec == null) return back;
             for (int i = 0; i < rec.defs.Length; i++)
-                if (rec.delivered[i] > 0) back.Add(new KeyValuePair<string, int>(rec.defs[i], rec.delivered[i]));
+                if (rec.delivered[i] > 0 && i < 0) back.Add(new KeyValuePair<string, int>(rec.defs[i], rec.delivered[i]));
             Clear(rec);
             return back;
         }
